<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\{Item,Menu,Recipe,MealPlan,KitchenIssue,StockTransaction}; use Illuminate\Http\Request;
class KitchenController extends Controller { public function index(){ $items=Item::all(); $menus=Menu::latest()->get(); $recipes=Recipe::latest()->limit(100)->get(); $plans=MealPlan::latest('plan_date')->limit(100)->get(); $issues=KitchenIssue::latest('issue_date')->limit(100)->get(); $consumption=KitchenIssue::selectRaw('item_id,sum(quantity) total_qty')->groupBy('item_id')->get(); return view('admin.kitchen.index',compact('items','menus','recipes','plans','issues','consumption')); } public function storeMenu(Request $r){ Menu::create($r->validate(['name'=>'required','meal_type'=>'required'])); return back()->with('success','Menu created'); } public function storeRecipe(Request $r){ Recipe::create($r->validate(['menu_id'=>'required|exists:menus,id','item_id'=>'required|exists:items,id','qty_per_serving'=>'required|numeric|min:0.0001'])); return back()->with('success','Recipe added'); } public function storePlan(Request $r){ MealPlan::create($r->validate(['plan_date'=>'required|date','menu_id'=>'required|exists:menus,id','planned_servings'=>'required|integer|min:1'])); return back()->with('success','Meal plan created'); } public function issue(Request $r){ $d=$r->validate(['issue_date'=>'required|date','item_id'=>'required|exists:items,id','quantity'=>'required|numeric|min:0.001']); $k=KitchenIssue::create($d+['remarks'=>$r->input('remarks')]); StockTransaction::create(['item_id'=>$d['item_id'],'txn_type'=>'KITCHEN_ISSUE','quantity'=>$d['quantity'],'unit_cost'=>0,'reference_type'=>KitchenIssue::class,'reference_id'=>$k->id,'txn_at'=>$d['issue_date'],'remarks'=>$r->input('remarks','Kitchen issue')]); return back()->with('success','Kitchen issue posted'); }}
